core_reasoning_2:
\textbf{Claim.}
For based SU(2) loops \(C_1\) and \(C_2\), the normalized single-trace relation is
\[
w(C_1)w(C_2)=\frac{1}{2}w(C_1C_2)+\frac{1}{2}w(C_1\overline{C}_2).
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & N=2.\\
(P2) & X:=U(C_1),\quad Y:=U(C_2).\\
(P3) & w(C):=N^{-1}\operatorname{tr}(U(C)).\\
(P4) & U(C_1C_2):=U(C_1)U(C_2)=XY.\\
(P5) & U(C_1\overline{C}_2):=U(C_1)U(C_2)^{\dagger}=XY^{\dagger}.\\
(P6) & \operatorname{tr}(X)\operatorname{tr}(Y)=\operatorname{tr}(XY)+\operatorname{tr}(XY^{\dagger})\quad\text{for }X,Y\in SU(2).
\end{array}
\]

\textbf{Derivation.}
\begin{align}
w(C_1)w(C_2)
&=\left(\frac{1}{2}\operatorname{tr}(X)\right)
  \left(\frac{1}{2}\operatorname{tr}(Y)\right) &&\text{by (P1), (P2), (P3)}\\
&=\frac{1}{4}\operatorname{tr}(X)\operatorname{tr}(Y) &&\text{multiply factors}\\
&=\frac{1}{4}\left[\operatorname{tr}(XY)+\operatorname{tr}(XY^{\dagger})\right] &&\text{by (P6)}\\
&=\frac{1}{2}\left(\frac{1}{2}\operatorname{tr}(XY)\right)+
  \frac{1}{2}\left(\frac{1}{2}\operatorname{tr}(XY^{\dagger})\right) &&\text{split the factor }1/4\\
&=\frac{1}{2}w(C_1C_2)+\frac{1}{2}w(C_1\overline{C}_2) &&\text{by (P3), (P4), (P5).}
\end{align}

\textbf{Final Result.}
\[\boxed{w(C_1)w(C_2)=\frac{1}{2}w(C_1C_2)+\frac{1}{2}w(C_1\overline{C}_2)}\]
\hfill$\blacksquare$

core_reasoning_8:
\textbf{Claim.}
If the two-dimensional loop count is
\(N_{\mathrm{loop}}^{(2\mathrm{D})}(L)\simeq A_{2\mathrm{D}}L^{-2}3^L\) and
\(R(L):=N_{\mathrm{eqn}}^{(2\mathrm{D})}(L)/N_{\mathrm{loop}}^{(2\mathrm{D})}(L)\simeq 1-c/L^{\delta}\), then
\[
N_{\mathrm{eqn}}^{(2\mathrm{D})}(L)\simeq A_{2\mathrm{D}}L^{-2}3^L\left(1-\frac{c}{L^{\delta}}\right).
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & N_{\mathrm{loop}}^{(2\mathrm{D})}(L)\simeq A_{2\mathrm{D}}L^{-2}3^L.\\
(P2) & R(L):=\dfrac{N_{\mathrm{eqn}}^{(2\mathrm{D})}(L)}{N_{\mathrm{loop}}^{(2\mathrm{D})}(L)}.\\
(P3) & R(L)\simeq 1-c/L^{\delta}.\\
(P4) & N_{\mathrm{loop}}^{(2\mathrm{D})}(L)\neq0.
\end{array}
\]

\textbf{Derivation.}
\begin{align}
R(L)
&:=\frac{N_{\mathrm{eqn}}^{(2\mathrm{D})}(L)}{N_{\mathrm{loop}}^{(2\mathrm{D})}(L)} &&\text{by (P2)}\\
N_{\mathrm{eqn}}^{(2\mathrm{D})}(L)
&=R(L)N_{\mathrm{loop}}^{(2\mathrm{D})}(L) &&\text{multiply by }N_{\mathrm{loop}}^{(2\mathrm{D})}(L)\text{ using (P4)}\\
&\simeq\left(1-\frac{c}{L^{\delta}}\right)A_{2\mathrm{D}}L^{-2}3^L &&\text{by (P1), (P3)}\\
&=A_{2\mathrm{D}}L^{-2}3^L\left(1-\frac{c}{L^{\delta}}\right) &&\text{commutativity of multiplication.}
\end{align}

\textbf{Final Result.}
\[\boxed{N_{\mathrm{eqn}}^{(2\mathrm{D})}(L)\simeq A_{2\mathrm{D}}L^{-2}3^L\left(1-\frac{c}{L^{\delta}}\right)}\]
\hfill$\blacksquare$
